#include "tcm.h"

#define TCM_SIZE_SHIFT          2U
#define TCM_SIZE_MASK           0x1FUL
#define TCM_WAITSTATES_SHIFT    8U
#define TCM_ENABLE_EL2          (1UL << 1)
#define TCM_ENABLE_EL10         (1UL << 0)
#define TCM_BASE_SHIFT          13U     /* TRM table 3-136: [31:13] */

#define MEMPROT_RAMPROTIMP      (1UL << 4)
#define MEMPROT_RAMPROTEN       (1UL << 0)


static unsigned long read_atcmregionr(void)
{
    unsigned long value;
    __asm volatile ("mrc p15, 0, %0, c9, c1, 0" : "=r" (value));
    return value;
}

static unsigned long read_btcmregionr(void)
{
    unsigned long value;
    __asm volatile ("mrc p15, 0, %0, c9, c1, 1" : "=r" (value));
    return value;
}

static unsigned long read_ctcmregionr(void)
{
    unsigned long value;
    __asm volatile ("mrc p15, 0, %0, c9, c1, 2" : "=r" (value));
    return value;
}


/* SIZE is an encoding, not a shift count: 4 means 8KB and each step doubles,
   so 8KB << (field - 4).  Anything outside the documented range yields 0
   rather than a plausible-looking wrong number.  */

static unsigned long decode_size(unsigned int field)
{
    unsigned long bytes = 0UL;

    if ((field >= 4U) && (field <= 11U))
    {
        bytes = 0x2000UL << (field - 4U);
    }

    return bytes;
}


void tcm_read_bank(unsigned int index, tcm_bank_t *bank_ptr)
{
    unsigned long raw;

    if (bank_ptr == 0)
    {
        return;
    }

    switch (index)
    {
        case 0U:  raw = read_atcmregionr(); break;
        case 1U:  raw = read_btcmregionr(); break;
        case 2U:  raw = read_ctcmregionr(); break;
        default:  raw = 0UL;                break;
    }

    bank_ptr->raw         = raw;
    bank_ptr->base        = raw & ~((1UL << TCM_BASE_SHIFT) - 1UL);
    bank_ptr->size_field  = (unsigned int) ((raw >> TCM_SIZE_SHIFT) & TCM_SIZE_MASK);
    bank_ptr->size_bytes  = decode_size(bank_ptr->size_field);
    bank_ptr->wait_states = (unsigned int) ((raw >> TCM_WAITSTATES_SHIFT) & 1UL);
    bank_ptr->enable_el2  = ((raw & TCM_ENABLE_EL2) != 0UL) ? 1U : 0U;
    bank_ptr->enable_el10 = ((raw & TCM_ENABLE_EL10) != 0UL) ? 1U : 0U;
}


unsigned long tcm_read_memprotctlr(void)
{
    unsigned long value;

    /* Note opc1 is 1 here, not 0 as for the region registers.  */

    __asm volatile ("mrc p15, 1, %0, c9, c1, 2" : "=r" (value));
    return value;
}


unsigned int tcm_ecc_implemented(void)
{
    return ((tcm_read_memprotctlr() & MEMPROT_RAMPROTIMP) != 0UL) ? 1U : 0U;
}


unsigned int tcm_ecc_enabled(void)
{
    unsigned long ctlr = tcm_read_memprotctlr();

    /* RAMPROTEN is ignored when RAMPROTIMP is 0: the TRM says the design
       behaves as if it were 0, so report it that way rather than echoing a
       bit that has no effect.  */

    if ((ctlr & MEMPROT_RAMPROTIMP) == 0UL)
    {
        return 0U;
    }

    return ((ctlr & MEMPROT_RAMPROTEN) != 0UL) ? 1U : 0U;
}


static void write_regionr(unsigned int index, unsigned long value)
{
    switch (index)
    {
        case 0U:
            __asm volatile ("mcr p15, 0, %0, c9, c1, 0" :: "r" (value) : "memory");
            break;
        case 1U:
            __asm volatile ("mcr p15, 0, %0, c9, c1, 1" :: "r" (value) : "memory");
            break;
        case 2U:
            __asm volatile ("mcr p15, 0, %0, c9, c1, 2" :: "r" (value) : "memory");
            break;
        default:
            return;
    }

    __asm volatile ("isb sy" ::: "memory");
}


unsigned int tcm_enable(unsigned int index, unsigned long base)
{
    tcm_bank_t  bank;
    unsigned long value;

    if (index > 2U)
    {
        return 0U;
    }

    tcm_read_bank(index, &bank);

    if (bank.size_bytes == 0UL)
    {
        return 0U;                      /* not implemented; nothing to enable */
    }

    /* Size-aligned, per TRM 6.2.  Rejecting a misaligned base is better than
       programming it and discovering later that the bank answers somewhere
       unexpected.  */

    if ((base & (bank.size_bytes - 1UL)) != 0UL)
    {
        return 0U;
    }

    /* Preserve the read-only SIZE and WAITSTATES fields as read: they describe
       the hardware and writing a different value there would be meaningless.  */

    value = (base & ~((1UL << TCM_BASE_SHIFT) - 1UL))
          | (bank.raw & ((TCM_SIZE_MASK << TCM_SIZE_SHIFT) | (1UL << TCM_WAITSTATES_SHIFT)))
          | TCM_ENABLE_EL2
          | TCM_ENABLE_EL10;

    write_regionr(index, value);

    /* Read back rather than trusting the write.  */

    tcm_read_bank(index, &bank);

    /* ENABLEEL10 is the criterion, not both enables.  Writing ENABLEEL2 from
       EL1 is ignored -- measured on BTCM and CTCM, where the base and bit 0 took
       while bit 1 stayed clear -- so requiring it here would report failure for
       a bank that is perfectly usable at the level this code runs at.  EL2
       access is arranged in entry.S, before the drop.  */

    return ((bank.base == (base & ~((1UL << TCM_BASE_SHIFT) - 1UL))) &&
            (bank.enable_el10 != 0U)) ? 1U : 0U;
}


void tcm_preload(unsigned int index, unsigned long base, unsigned long bytes)
{
    if (index == 0U)
    {
        /* ATCM: 64-bit stores at 64-bit alignment.  TRM 6.2.2 is explicit that
           STR of a word is not sufficient here, so this writes unsigned long
           long and the generated code is checked to be STRD or STM rather than
           two word stores.  */

        volatile unsigned long long *p = (volatile unsigned long long *) base;
        unsigned long count = bytes / 8UL;
        unsigned long i;

        for (i = 0UL; i < count; i++)
        {
            p[i] = 0ULL;
        }
    }
    else
    {
        /* BTCM and CTCM: 32-bit stores at 32-bit alignment are enough.  */

        volatile unsigned int *p = (volatile unsigned int *) base;
        unsigned long count = bytes / 4UL;
        unsigned long i;

        for (i = 0UL; i < count; i++)
        {
            p[i] = 0U;
        }
    }

    __asm volatile ("dsb sy" ::: "memory");
}
